import 'dart:convert';
import 'dart:io';

import 'package:path_provider/path_provider.dart';
import 'package:uuid/uuid.dart';

/// A queued local write that must be replayed once the device is online.
///
/// `idempotencyKey` is generated by the app before the write and is persisted
/// alongside the record. On replay, the server uses it to detect a retry, so a
/// flaky connection can never produce two incidents, two corrective actions,
/// or two approvals from one user tap. This is the core of the duplicate
/// submission protection required by the workflow rules.
class OutboxEntry {
  const OutboxEntry({
    required this.id,
    required this.idempotencyKey,
    required this.table,
    required this.operation,
    required this.payload,
    required this.createdAt,
    this.attempts = 0,
    this.lastError,
  });

  final String id;
  final String idempotencyKey;
  final String table;
  final OutboxOperation operation;
  final Map<String, dynamic> payload;
  final DateTime createdAt;
  final int attempts;
  final String? lastError;

  factory OutboxEntry.fromJson(Map<String, dynamic> j) => OutboxEntry(
    id: j['id'] as String,
    idempotencyKey: j['idempotency_key'] as String,
    table: j['table'] as String,
    operation: OutboxOperation.values.firstWhere(
      (o) => o.wire == j['operation'],
      orElse: () => OutboxOperation.insert,
    ),
    payload: Map<String, dynamic>.from(j['payload'] as Map),
    createdAt: DateTime.parse(j['created_at'] as String),
    attempts: (j['attempts'] as num?)?.toInt() ?? 0,
    lastError: j['last_error'] as String?,
  );

  Map<String, dynamic> toJson() => {
    'id': id,
    'idempotency_key': idempotencyKey,
    'table': table,
    'operation': operation.wire,
    'payload': payload,
    'created_at': createdAt.toIso8601String(),
    'attempts': attempts,
    'last_error': lastError,
  };
}

enum OutboxOperation {
  insert('INSERT'),
  update('UPDATE');

  const OutboxOperation(this.wire);

  final String wire;
}

/// Append-only on-disk outbox for offline writes.
///
/// Writes are flushed to disk on every enqueue so that a crash or a force-kill
/// (common on low-end Android devices in the field) never silently loses a
/// safety report. This is deliberate: an unsent incident report is worse than
/// an annoying one.
class Outbox {
  Outbox._(this._file);

  static Outbox? _instance;
  final File _file;
  List<OutboxEntry> _entries = const [];

  static Future<Outbox> instance() async {
    if (_instance != null) return _instance!;
    final dir = await getApplicationDocumentsDirectory();
    _instance = Outbox._(File('${dir.path}/outbox.json'));
    await _instance!._load();
    return _instance!;
  }

  Future<void> _load() async {
    if (!await _file.exists()) {
      _entries = const [];
      return;
    }
    try {
      final raw = await _file.readAsString();
      final decoded = raw.isEmpty ? const [] : (jsonDecode(raw) as List);
      _entries = decoded
          .cast<Map<String, dynamic>>()
          .map(OutboxEntry.fromJson)
          .toList(growable: false);
    } catch (_) {
      // A corrupt outbox must never brick the app. Preserve the file for
      // forensics and start clean.
      final backup = File('${_file.path}.corrupt');
      if (await _file.exists()) await _file.copy(backup.path);
      _entries = const [];
    }
  }

  List<OutboxEntry> get entries => List.unmodifiable(_entries);

  int get length => _entries.length;

  bool get isEmpty => _entries.isEmpty;

  /// Creates a queued entry and returns the idempotency key the caller must
  /// embed in the payload as `client_request_id`.
  Future<String> enqueue({
    required String table,
    required OutboxOperation operation,
    required Map<String, dynamic> payload,
  }) async {
    final entry = OutboxEntry(
      id: const Uuid().v4(),
      idempotencyKey: const Uuid().v4(),
      table: table,
      operation: operation,
      payload: payload,
      createdAt: DateTime.now(),
    );
    _entries = [..._entries, entry];
    await _flush();
    return entry.idempotencyKey;
  }

  OutboxEntry? get(String id) {
    for (final e in _entries) {
      if (e.id == id) return e;
    }
    return null;
  }

  Future<void> remove(String id) async {
    _entries = _entries.where((e) => e.id != id).toList(growable: false);
    await _flush();
  }

  Future<void> markFailure(String id, String error) async {
    _entries = _entries
        .map(
          (e) => e.id == id
              ? OutboxEntry(
                  id: e.id,
                  idempotencyKey: e.idempotencyKey,
                  table: e.table,
                  operation: e.operation,
                  payload: e.payload,
                  createdAt: e.createdAt,
                  attempts: e.attempts + 1,
                  lastError: error,
                )
              : e,
        )
        .toList(growable: false);
    await _flush();
  }

  Future<void> clear() async {
    _entries = const [];
    await _flush();
  }

  Future<void> _flush() => _file.writeAsString(
    jsonEncode(_entries.map((e) => e.toJson()).toList(growable: false)),
  );
}

/// Returns a freshly minted idempotency key for an online write, used to make
/// even the happy path retry-safe.
String newIdempotencyKey() => const Uuid().v4();
